class Transaction {
    private final String refId;
    private final String accountId;
    private final BigDecimal amount;
    Transaction(String refId, String accountId, BigDecimal amount) {
        this.refId = refId; this.accountId = accountId; this.amount = amount;
    }
    String getRefId() { return refId; }
}

// ─── Would be in service/TransactionAnalyzer.java ───
class TransactionAnalyzer {
    private static final Logger log = Logger.getLogger(TransactionAnalyzer.class.getName());

    // O(n): check every element until found.
    boolean linearContains(List<Transaction> batch, String refId) {
        long ops = 0;
        for (Transaction t : batch) {
            ops++;
            if (t.getRefId().equals(refId)) {
                final long f = ops;
                log.info(() -> "linearContains O(n): found after " + f + " ops");
                return true;
            }
        }
        return false;
    }

    // O(n) to build the map once, then O(1) per lookup.
    boolean mapContains(List<Transaction> batch, String refId) {
        Map<String, Transaction> index = new HashMap<>();
        for (Transaction t : batch) index.put(t.getRefId(), t); // build: O(n)
        boolean found = index.containsKey(refId);               // lookup: O(1)
        log.info(() -> "mapContains O(1) lookup: found=" + found + " (map built in O(n) once)");
        return found;
    }

    // O(n^2): compare every pair — slow and wasteful.
    boolean hasDuplicateNaive(List<Transaction> batch) {
        long ops = 0;
        for (int i = 0; i < batch.size(); i++) {
            for (int j = i + 1; j < batch.size(); j++) {
                ops++;
                if (batch.get(i).getRefId().equals(batch.get(j).getRefId())) {
                    final long f = ops;
                    log.warning(() -> "hasDuplicateNaive O(n^2): duplicate found after " + f + " ops");
                    return true;
                }
            }
        }
        return false;
    }

    // O(n): single pass with a HashSet — much faster.
    boolean hasDuplicateSet(List<Transaction> batch) {
        long ops = 0;
        Set<String> seen = new HashSet<>();
        for (Transaction t : batch) {
            ops++;
            if (!seen.add(t.getRefId())) {
                final long f = ops;
                log.warning(() -> "hasDuplicateSet O(n): duplicate found after " + f + " ops");
                return true;
            }
        }
        return false;
    }
}

